import { sql } from "drizzle-orm";
import { check, date, numeric, timestamp, uuid, type AnyPgColumn } from "drizzle-orm/pg-core";

/** uuid primary key generated by the database (gen_random_uuid, built into PostgreSQL 13+). */
export const pk = () => uuid("id").primaryKey().defaultRandom();

export const createdAt = () =>
  timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

export const tstz = (name: string) => timestamp(name, { withTimezone: true });

/** Money: numeric(12,2). Drizzle returns it as a string, which is what you want for money. */
export const money = (name: string) => numeric(name, { precision: 12, scale: 2 });

/** Calendar date as an ISO string (YYYY-MM-DD). */
export const day = (name: string) => date(name, { mode: "string" });

/**
 * Text column restricted to a fixed list of values, enforced by a CHECK constraint.
 * Checks are used instead of Postgres enums so adding a value later is a simple,
 * backward-compatible migration.
 *
 * Use this only on NOT NULL columns: a CHECK passes when its condition is NULL, so a nullable
 * column needs an explicit `col IS NULL OR col IN (...)`. When writing any CHECK, remember that
 * `NULL > 0` and `NULL IN (...)` are NULL, which passes, so guard nullable columns with IS NOT NULL.
 */
export function oneOf(name: string, column: AnyPgColumn, values: readonly string[]) {
  const list = values.map((v) => `'${v.replace(/'/g, "''")}'`).join(", ");
  return check(name, sql`${column} IN (${sql.raw(list)})`);
}

/** Used by hand-written SQL migrations: stands in for NULL inside exclusion constraints. */
export const ZERO_UUID = "00000000-0000-0000-0000-000000000000";
